// Detect a live drop (0 -> N) or a restock, and whether it's a limited pair
const b = $input.first().json.body || $input.first().json;
const available = Number(b.available ?? b.inventory_quantity ?? 0);
const previous = Number(b.old_available ?? b.previous_quantity ?? 0);
const title = b.title || b.product_title || 'New Pair';
const tags = (b.tags || '').toLowerCase();
const isLimited = /limited|exclusive|deadstock|collab/.test(tags);
let eventType = null;
if (previous <= 0 && available > 0) eventType = 'DROP';
else if (previous > 0 && available > previous) eventType = 'RESTOCK';
if (!eventType) { return []; }
return [{ json: {
  eventType, title, available, isLimited,
  handle: b.handle || '',
  price: b.price || '',
  image: b.image || b.featured_image || '',
  url: `https://sneakerfest.com/products/${b.handle || ''}`,
  detectedAt: new Date().toISOString()
} }];

const d = $('Detect Drop / Restock').item.json;
const link = $input.first().json.link || d.url;
const fire = d.isLimited ? '🔥🔥' : '🔥';
const verb = d.eventType === 'DROP' ? 'JUST DROPPED' : 'RESTOCKED';
const social = `${fire} ${d.title} ${verb} ${fire}\n${d.isLimited ? 'Limited pairs — ' : ''}${d.available} available now.\nCop before it's gone 👉 ${link}\n#SneakerFest #kicks`;
return [{ json: { ...d, link, social } }];
